/* Vitals in the Void — views. Each view returns {html, bind}. */
const VIEWS={};
const unit=u=>u?` <span class="t3 s">${esc(u)}</span>`:'';
const tabsHTML=(id,items,sel)=>`<div class="tabs" role="tablist" id="${id}">${items.map(([k,n,c])=>`<button role="tab" data-tab="${k}" aria-selected="${k===sel}">${n}${c?`<span class="count">${c}</span>`:''}</button>`).join('')}</div>`;
const bindTabs=(id,fn)=>$$(`#${id} [data-tab]`).forEach(b=>b.onclick=()=>{$$(`#${id} [data-tab]`).forEach(x=>x.setAttribute('aria-selected',x===b));fn(b.dataset.tab)});
function varOptions(sel,filter){const groups=[['Wearable (continuous)',v=>v.f==='cont'],['Daily',v=>v.f==='daily'],['Every 2 days',v=>v.f==='d2'],['Every 3 days',v=>v.f==='d3'],['Weekly lab tests (invasive)',v=>v.inv&&v.f!=='calc'],['Spacewalk',v=>v.f==='eva'],['Calculated',v=>v.f==='calc']];
 return groups.map(([n,f])=>`<optgroup label="${n}">${META.VARS.filter(v=>f(v)&&(!filter||filter(v))).map(v=>`<option value="${v.id}" ${v.id===sel?'selected':''}>${esc(v.n)}${v.u?' ('+esc(v.u)+')':''}</option>`).join('')}</optgroup>`).join('')}
function bindVar(root=document){root.querySelectorAll('[data-var]').forEach(b=>b.onclick=()=>openVar(b.dataset.var))}
const alertCard=(f,i=0)=>`<details class="att" data-lvl="${f.lvl}" ${i===0?'open':''}><summary><span class="dot" style="background:${COLV[f.lvl]}"></span><span class="grow"><b class="attname" role="link" tabindex="0" data-logvar="${f.v}" title="${logLabel(f.v)}">${esc(f.n)}</b>${f.cond?` <span class="t3 s">· ${esc(f.cond)}</span>`:''}<br><span class="s t2">${fmt(f.value,f.dp??VM(f.v).dp)} ${esc(f.u)} — expected ${fmt(f.E,f.dp??VM(f.v).dp)}</span></span>${st(f.lvl)}${CHEVD}</summary>
 <div class="body"><p class="s t2">${esc(f.why)}.${f.note?' '+esc(f.note)+'.':''}</p>${guideHTML(f.guide)}<div class="row" style="margin-top:12px;gap:8px"><button class="btn p sm" data-logvar="${f.v}">${ICON('<path d="M12 5v14M5 12h14"/>')}${logLabel(f.v)}</button><button class="btn sm" data-var="${f.v}">History & details</button></div></div></details>`;
/* where "log this metric" goes: check-in fields → Daily check-in, symptoms → Symptoms, spacewalk measures → Spacewalk debrief,
   calculated measures → their details (they are derived from other inputs), anything else → Log data › One value */
const logLabel=v=>{const m=VM(v)||{};return m.f==='calc'?'See how it is calculated':m.f==='eva'?'Log in spacewalk debrief':'Log a value'};
function goLog(v){const m=VM(v)||{};closeDrawer();
 if(m.f==='calc')return openVar(v);
 if(m.f==='eva'){U.focusVar=v;location.hash==='#eva'?render():location.hash='eva';return}
 if(String(v).startsWith('sym_')){U.logTab='sym'}else{U.oneVar=v;U.logTab=CHECKIN.includes(v)?'checkin':'single';U.focusVar=v}
 U.mtab='log';if(location.hash==='#monitor'||(!location.hash&&U.route==='monitor')){$$('#mtabs [data-tab]').forEach(x=>x.setAttribute('aria-selected',x.dataset.tab==='log'));monTab();$('#mainwrap').scrollTo({top:0,behavior:'smooth'})}else location.hash='monitor'}
document.addEventListener('click',e=>{const t=e.target.closest('[data-logvar]');if(!t)return;e.preventDefault();e.stopPropagation();goLog(t.dataset.logvar)},true);
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches&&e.target.matches('.attname')){e.preventDefault();e.stopPropagation();goLog(e.target.dataset.logvar)}},true);

/* ================= MONITOR ================= */
VIEWS.monitor=async()=>{const c=cur(),O=await api(`/api/crew/${c.id}/overview?mode=${U.mode}`);renderHeader(O.hdr);U.O=O;const due=O.sched.filter(s=>s.due).length;
 return{html:`${O.urgent?`<div class="banner l2" style="margin-bottom:18px">${st(2,'Urgent')}<div><b>A safety limit was crossed or an urgent symptom was reported.</b><div class="s t2">Re-measure now. If confirmed, follow the steps under “Needs attention” and contact the Crew Medical Officer.</div></div></div>`:''}
 ${tabsHTML('mtabs',[['overview','Overview'],['live','Live vitals'],['log','Log data'],['measures','Scheduled measures',due||'']],U.mtab)}<div id="mt"></div>`,
 bind(){bindTabs('mtabs',t=>{U.mtab=t;clearInterval(U.timer);monTab()});monTab()}}};
function monTab(){const box=$('#mt');if(!box)return;box.style.animation='none';void box.offsetWidth;box.style.animation='rise .35s var(--ease) both';({overview:monOverview,live:monLive,log:monLog,measures:monMeasures})[U.mtab]()}
function monOverview(){const O=U.O,c=cur(),sex=c.sex||STATE.settings.avatar||'F';const n=[2,1,0].map(l=>O.conds.filter(k=>k.lvl===l).length),nd=O.conds.filter(k=>k.lvl==null).length;
 const circ=2*Math.PI*46;
 $('#mt').innerHTML=`<div class="overview"><div class="card bodycard"><div class="row between"><h3>Body status</h3><span class="pill" title="Each body system uses the most recent value of every measure, wearable, daily, exam and lab">Latest of all data</span></div>
  <p class="s t3">Hover to identify a body part, click it for details and what to do.</p><div class="bodystage" id="stage">${bodySVG(O.regions,sex)}<div class="btip"></div></div>
  <div class="legend"><span><span class="dot" style="background:var(--ok)"></span>Nominal</span><span><span class="dot" style="background:var(--warn)"></span>Warning</span><span><span class="dot" style="background:var(--bad)"></span>Alert</span><span><span class="dot" style="background:${NONE}"></span>No data</span></div></div>
 <div class="stack gap16"><div class="card hi"><div class="score"><div class="gauge"><svg viewBox="0 0 112 112"><defs><linearGradient id="gg"><stop offset="0" stop-color="#79dce8"/><stop offset="1" stop-color="#ffffff"/></linearGradient></defs><circle class="trk" cx="56" cy="56" r="46"/><circle class="val" cx="56" cy="56" r="46" stroke-dasharray="${circ}" stroke-dashoffset="${circ}" id="gval"/></svg><b id="gnum">${O.index??'–'}</b></div>
   <div class="stack gap8 grow"><div><h3>Health index</h3><p class="s t2">Readings are compared with ${esc(c.name.split(' ')[0])}’s own expected values for day ${Math.floor(O.hdr.day)} (${esc(O.hdr.phase.toLowerCase())}).</p></div>
   <div class="counts"><button class="count" data-spot="2" title="Show the alerts"><span class="dot" style="background:var(--bad)"></span><b>${n[0]}</b>alert</button><button class="count" data-spot="1" title="Show the warnings"><span class="dot" style="background:var(--warn)"></span><b>${n[1]}</b>warning</button><button class="count" data-spot="0" title="Show the nominal systems"><span class="dot" style="background:var(--ok)"></span><b>${n[2]}</b>nominal</button>${nd?`<button class="count" data-spot="nd" title="Show what has no data"><span class="dot" style="background:${NONE}"></span><b>${nd}</b>no data</button>`:''}</div></div></div></div>
  <div class="card"><div class="row between"><h3>Needs attention</h3><button class="btn sm" id="goLog">${ICON('<path d="M12 5v14M5 12h14"/>')}Log a measurement</button></div>
   <div class="stack gap8" style="margin-top:12px">${O.actions.length?O.actions.slice(0,4).map(alertCard).join('')+(O.actions.length>4?`<div id="moreAtt" class="stack gap8 hidden">${O.actions.slice(4).map((a,i)=>alertCard(a,1)).join('')}</div><button class="btn ghost" id="showMore">Show ${O.actions.length-4} more</button>`:''):`<div class="empty">${st(0,'All clear')}<p style="margin-top:8px">Everything is within ${esc(c.name.split(' ')[0])}’s expected range.</p></div>`}</div>
   ${O.actions.length?'<p class="xs t3" style="margin-top:10px">A Warning becomes an Alert only if it persists without recovering, or at once if a value is dangerous.</p>':''}</div>
  <div class="card"><h3>Body systems</h3><div class="syslist" style="margin-top:12px">${O.conds.map(k=>{const t=k.top;const sub=k.sym.length&&k.lvl&&(!t||t.lvl<k.lvl)?'Symptom: '+k.sym.join(', ').toLowerCase():t?`${t.n}`:k.count?`${k.count} measures in range`:'Measurement due';
   return`<button class="sys" data-cond="${k.id}" data-lvl="${k.lvl==null?'nd':k.lvl}"><span class="dot" style="background:${k.lvl==null?NONE:COLV[k.lvl]}"></span><span class="nm">${esc(k.short)}<small>${esc(sub)}</small></span></button>`}).join('')}</div></div></div></div>`;
 requestAnimationFrame(()=>{const g=$('#gval');if(g&&O.index!=null)g.style.strokeDashoffset=circ*(1-O.index/100);countUp($('#gnum'),O.index)});
 bindBody($('#stage'),r=>openRegion(r),O.regions);
 $$('[data-cond]').forEach(b=>b.onclick=()=>openCond(b.dataset.cond));$$('[data-spot]').forEach(b=>b.onclick=()=>spotlight(b.dataset.spot,b));const sm=$('#showMore');if(sm)sm.onclick=()=>{const m=$('#moreAtt');const h=m.classList.toggle('hidden');sm.textContent=h?`Show ${O.actions.length-4} more`:'Show fewer'};$('#goLog').onclick=()=>{U.mtab='log';$$('#mtabs [data-tab]').forEach(x=>x.setAttribute('aria-selected',x.dataset.tab==='log'));monTab()}}

/* ---- wearable battery & fast recharge (state lives on the server, see backend/wearable.py) ---- */
const BAT_ICON='<rect x="2" y="7" width="16" height="10" rx="2"/><path d="M21 10v4"/>';
const batCol=b=>b.charging?(b.fast?'var(--warn)':'var(--ok)'):b.pct<10?'var(--bad)':b.pct<20?'var(--warn)':b.pct<35?'var(--warn)':'var(--ok)';
const hrsTxt=h=>h>=24?(h/24).toFixed(1)+' days':h.toFixed(1)+' hours';
function batteryHTML(b){const col=batCol(b),low=b.pct<20&&!b.charging;
 const badge=b.charging?st(b.fast?1:0,b.fast?'Fast-charging':'Charging'):st(b.pct<10?2:b.pct<35?1:0,b.pct<10?'Battery critical':b.pct<20?'Low battery':b.pct<35?'Moderate':'Charged');
 return`<div class="bat-widget${low?' is-low':''}" id="batWidget" data-mode="${b.fast?'fast':'std'}" data-ch="${b.charging?1:0}">
 <div class="row between" style="flex-wrap:wrap;gap:10px"><div class="row" style="gap:10px">${ICON(BAT_ICON)}<div><b>Wearable smart device & battery</b> <span class="num b" id="batPct" style="margin-left:6px;color:${col}">${Math.round(b.pct)}%</span>
  <div class="xs t3" id="batSub">${b.charging?(b.fast?'⚡ Fast-Recharge · +35 %/s simulated fill (higher cell stress)':'Standard magnetic charge · +8.75 %/s simulated fill'):b.streaming?'Streaming continuously · uses about 3.5 % per hour of wear':'Standby (wearable connected)'}</div></div></div>
  <div class="row" style="gap:8px;flex-wrap:wrap">${badge}<button type="button" class="bat-toggle" id="batFast" aria-pressed="${b.fast}" title="Fast-Recharge fills 4× faster but wears the battery more"><span class="bat-toggle-track" aria-hidden="true"></span><span>⚡ Fast-Recharge</span></button>
  <button type="button" class="btn sm" id="batTest" title="Set the battery to 12 % to try the low-battery warnings">Test &lt;15%</button><button type="button" class="btn p sm" id="batCharge">${b.charging?'Stop charging':b.fast?'⚡ Fast recharge':'Recharge to 100%'}</button></div></div>
 <div class="bat-bar"><div class="bat-fill${b.charging?' is-charging':''}${b.charging&&b.fast?' is-fast':''}" id="batFill" style="width:${b.pct}%;background-color:${col}"></div><span class="bat-ticks" aria-hidden="true"><i style="left:20%"></i><i style="left:15%"></i><i style="left:10%"></i><i style="left:5%"></i></span></div>
 <div class="batgrid"><div class="sub"><span class="xs t3" id="bat1L">${b.charging?'Time to 100%':'Predicted time to empty'}</span><div class="num b" id="bat1" style="color:${col}">${b.charging?b.time_to_full_s+' s':hrsTxt(b.time_to_empty_h)}</div><div class="xs t3">Mode: ${b.charging?(b.fast?'4× Fast-Recharge':'Standard charge'):b.streaming?'Active streaming':'Standby'}</div></div>
  <div class="sub"><span class="xs t3">${b.charging?'Charge rate':'Discharge rate'}</span><div class="num b">${b.charging?'+'+b.charge_rate+' % / s':b.discharge_rate+' % / hr'}</div><div class="xs t3">${b.fast?'4× fill speed · ~1.1 % wear per full charge':'About '+Math.round(b.discharge_rate*24)+' % per 24 h · 0.05 % wear per charge'}</div></div>
  <div class="sub"><span class="xs t3">Battery health & cycles</span><div class="num b" id="batH" style="color:${b.health<90?'var(--bad)':b.health<95?'var(--warn)':'var(--ok)'}">${b.health.toFixed(1)}% · ${b.cycles} cycles</div><div class="xs t3">${b.fast_24h?`Fast-Recharge uses (24 h): ${b.fast_24h}${b.fast_24h>=3?' · high wear':''}`:'Lithium-ion smart band · low wear'}</div></div></div>
 ${low?`<div class="banner l${b.pct<10?2:1}" style="padding:10px 13px">${st(b.pct<10?2:1,b.pct<10?'Critical':'Low battery')}<span class="s"><b>Wearable battery at ${Math.round(b.pct)}%.</b> Put it on the magnetic charger or swap to the spare band soon to avoid a gap in continuous monitoring.</span></div>`:''}
 ${b.wear_alert?`<div class="banner l${b.wear_alert}" style="padding:10px 13px">${st(b.wear_alert,b.wear_alert>1?'Cell wear':'Frequent Fast-Recharge')}<span class="s"><b>Fast-Recharge used ${b.fast_24h} times in 24 h</b> (battery health ${b.health.toFixed(1)}%). Frequent fast charging wears lithium-ion cells faster — use standard recharge when there is time.</span></div>`:''}</div>`}
function bindBattery(){const c=cur();const act=async(action,value)=>{const r=await api(`/api/crew/${c.id}/battery`,{body:{action,value}});if(r.msg)toast(r.msg);W.bat=r.battery;drawBattery(true);wearSchedule();pollWearEvents()};
 $('#batFast').onclick=()=>act('fast',!W.bat.fast);$('#batCharge').onclick=()=>act('charge');$('#batTest').onclick=()=>act('testlow')}
function drawBattery(full){const b=W.bat,box=$('#batBox');if(!box||!b)return;const w=$('#batWidget');
 if(full||!w||w.dataset.mode!==(b.fast?'fast':'std')||w.dataset.ch!==(b.charging?'1':'0')||(b.pct<20)!==w.classList.contains('is-low')){box.innerHTML=batteryHTML(b);bindBattery();return}
 const col=batCol(b);$('#batFill').style.width=b.pct+'%';$('#batFill').style.backgroundColor=col;$('#batPct').textContent=Math.round(b.pct)+'%';$('#batPct').style.color=col;
 $('#bat1').textContent=b.charging?b.time_to_full_s+' s':hrsTxt(b.time_to_empty_h);$('#bat1').style.color=col;$('#batH').textContent=`${b.health.toFixed(1)}% · ${b.cycles} cycles`}
/* ---- Earth Flight Surgeon Uplink (preventive escalation relay) ---- */
function uplinkHTML(u){const flag=u.flagged&&u.mode==='queued',act=u.mode==='active',ackd=u.mode==='acknowledged'&&u.flagged,p=u.primary;
 return`<div class="card uplink-card${flag||ackd?' is-flagged':act?' is-active':''}"><div class="row between" style="gap:10px;flex-wrap:wrap"><div class="row" style="gap:9px"><span class="uplink-dot" aria-hidden="true"></span><div><h3 style="font-size:15.5px;margin:0">Earth Flight Surgeon Uplink</h3><div class="xs t3">Preventive escalation relay to the flight surgeons on Earth</div></div></div>
 <button type="button" class="uplink-badge${flag||ackd?' is-amber':act?' is-cyan':''}" data-upopen>${flag?'⚠ Early warning flagged':act?'📡 Transmitting packet':ackd?'✓ Relayed to Earth':'● Nominal link'}</button></div>
 <div class="row between" style="margin-top:10px;gap:8px;flex-wrap:wrap"><span class="xs t3">Transmission status</span><span class="num b" data-upstatus style="font-size:12.5px;color:${flag?'var(--warn)':act?'#79dce8':ackd?'var(--ok)':'#d8f8ff'}">${esc(u.label)}</span></div>
 ${p?`<button type="button" class="uplink-alert-btn" data-upopen style="margin-top:10px"><div class="grow"><div class="s b" style="color:${act?'#d8f8ff':'#ffe49e'}">${esc(p.name)}: ${fmt(p.val,p.dp)} ${esc(p.unit)} (ETA: ${esc(u.eta)})</div><div class="xs t2" style="margin-top:2px">24–48 h negative drift flagged for the Earth flight surgeons · click to inspect the packet and interim countermeasure</div></div><span class="btn sm" style="flex:none">${act?'View live link':'Inspect alert'}</span></button>`
  :`<div class="sub xs t3" style="margin-top:10px;padding:9px 11px">All 24–48 h trends are within the personal envelope. The early-warning relay is armed.</div>`}
 <div class="row between" style="margin-top:10px;gap:8px;flex-wrap:wrap"><button type="button" class="btn sm" data-upsim>${u.sim?'Clear drift test':'Test 48h drift'}</button><button type="button" class="btn sm ${p?'p':''}" data-upopen>${p?'Open escalation packet':'Link details'}</button></div></div>`}
function bindUplink(root){root.querySelectorAll('[data-upopen]').forEach(b=>b.onclick=openUplink);const s=root.querySelector('[data-upsim]');if(s)s.onclick=()=>uplinkAct('sim')}
async function uplinkAct(action){const c=cur();const r=await api(`/api/crew/${c.id}/uplink`,{body:{action}});if(r.msg)toast(r.msg);W.up=r.uplink;drawUplink();wearSchedule();if($('#modal').classList.contains('on')&&$('#upModal'))openUplink();return r}
function drawUplink(){const box=$('#uplinkBox');if(!box||!W.up)return;box.innerHTML=uplinkHTML(W.up);bindUplink(box)}
function uplinkChart(u){const p=u.primary;if(!p)return'';const pts=p.pts&&p.pts.length>=2?p.pts:[[0,p.E],[1,p.val]];const W_=520,H=108,px=28,py=14;
 let vs=pts.map(x=>x[1]).concat([p.E,p.crit]);let lo=Math.min(...vs),hi=Math.max(...vs);const sp=Math.max(.01,hi-lo);lo-=sp*.15;hi+=sp*.15;
 const x0=pts[0][0],xl=pts[pts.length-1][0],xp=xl+Math.max(.8,Math.min(3.5,p.h2c/24));const X=x=>px+(x-x0)/Math.max(.1,xp-x0)*(W_-px*2),Y=v=>H-py-(v-lo)/Math.max(.01,hi-lo)*(H-py*2);const L=pts[pts.length-1];
 return`<svg class="uplink-chart" viewBox="0 0 ${W_} ${H}" preserveAspectRatio="none"><line x1="${px}" y1="${Y(p.E)}" x2="${W_-px}" y2="${Y(p.E)}" stroke="rgba(121,220,232,.45)" stroke-dasharray="4 4"/><text x="${px+4}" y="${Math.max(11,Y(p.E)-4)}" fill="#79dce8" font-size="9.5" font-family="IBM Plex Mono,monospace">Expected ${fmt(p.E,p.dp)}</text>
 <line x1="${px}" y1="${Y(p.crit)}" x2="${W_-px}" y2="${Y(p.crit)}" stroke="rgba(239,91,91,.75)" stroke-dasharray="5 3"/><text x="${W_-px-4}" y="${Math.max(11,Y(p.crit)-4)}" text-anchor="end" fill="#ff9e9e" font-size="9.5" font-family="IBM Plex Mono,monospace">Critical ${fmt(p.crit,p.dp)} ${esc(p.unit)}</text>
 <polyline points="${pts.map(q=>X(q[0]).toFixed(1)+','+Y(q[1]).toFixed(1)).join(' ')}" fill="none" stroke="#f5b941" stroke-width="2.2" stroke-linejoin="round"/><line x1="${X(L[0])}" y1="${Y(L[1])}" x2="${X(xp)}" y2="${Y(p.crit)}" stroke="#ef5b5b" stroke-dasharray="3 3" stroke-width="1.8"/>
 <circle cx="${X(L[0])}" cy="${Y(L[1])}" r="4" fill="#f5b941" stroke="#fff" stroke-width="1.2"/><circle cx="${X(xp)}" cy="${Y(p.crit)}" r="4" fill="#ef5b5b"/></svg>`}
function openUplink(){const u=W.up,c=cur();if(!u)return;
 if(!u.primary){modal(`<div id="upModal"><div class="row between"><div><h3>Earth Flight Surgeon Uplink</h3><p class="s t3" style="margin-top:4px">Preventive escalation relay · ${esc(c.name)}</p></div><button class="btn sm" id="upX">Close</button></div>
  <div class="banner l0" style="margin-top:12px">${st(0,'Standby')}<span class="s"><b>All monitored 24–48 h trends are nominal.</b> No escalation packet is queued for the flight surgeons on Earth. Signal delay from here: ${u.delay>=60?Math.round(u.delay/60)+' min':u.delay+' s'}.</span></div>
  <div class="row between" style="margin-top:16px"><button class="btn sm" id="upSim">Test 48h drift</button><button class="btn p sm" id="upX2">Done</button></div></div>`);
  $('#upX').onclick=$('#upX2').onclick=closeModal;$('#upSim').onclick=()=>uplinkAct('sim');return}
 const p=u.primary,g=u.guide;
 modal(`<div id="upModal"><div class="row between" style="align-items:flex-start"><div><div class="row" style="gap:8px"><h3>Earth Flight Surgeon Uplink</h3>${st(u.mode==='active'?0:1,u.mode==='active'?'Uplink active':u.mode==='acknowledged'?'Delivered':'Early warning')}</div><p class="s t3" style="margin-top:4px">Preventive escalation relay · ${esc(c.name)} · mission day ${Math.floor(U.O?U.O.hdr.day:0)}</p></div><button class="btn sm" id="upX">Close</button></div>
 <div class="grid cols2" style="gap:12px;margin-top:12px"><div class="sub" style="box-shadow:inset 0 0 0 1px rgba(245,185,65,.45)"><div class="xs t3">Drifting measure</div><div class="b" style="font-size:15px;margin-top:4px;color:#ffe49e">${esc(p.name)}</div><div class="num s" style="margin-top:4px">Now <b>${fmt(p.val,p.dp)} ${esc(p.unit)}</b> <span class="t3">(expected ${fmt(p.E,p.dp)})</span></div><div class="xs t2" style="margin-top:4px">48 h drift: <b class="num">${p.slope>=0?'+':''}${p.slope.toFixed(2)} ${esc(p.unit)}/day</b>${u.symptoms.length?' · Symptoms: '+esc(u.symptoms.join(', ')):''}</div></div>
  <div class="sub" style="box-shadow:inset 0 0 0 1px rgba(239,91,91,.45)"><div class="xs t3">Projected time to critical threshold</div><div class="num b" style="font-size:17px;margin-top:4px;color:#ff9e9e;overflow-wrap:anywhere">${esc(u.eta)}</div><div class="xs t2" style="margin-top:4px">Threshold <b class="num">${fmt(p.crit,p.dp)} ${esc(p.unit)}</b> · Link: <b data-upstatus>${esc(u.label)}</b></div></div></div>
 <div style="margin-top:12px"><div class="xs t3" style="margin-bottom:6px">48-hour trajectory and projection to the critical threshold</div>${uplinkChart(u)}</div>
 <div style="margin-top:14px"><div class="row between" style="margin-bottom:6px"><span class="s b">Medical telemetry report for the flight surgeons on Earth</span><span class="xs t3">Escalation packet</span></div><pre class="uplink-packet">${esc(u.packet)}</pre></div>
 <div class="uplink-cm" style="margin-top:14px"><div class="row between" style="gap:8px;margin-bottom:6px"><span class="s b" style="color:#b8ffd8">Interim countermeasure</span><span class="pill">While awaiting Earth review</span></div><p class="s" style="margin:0;color:#e7fff2">${esc(u.interim)}</p>${g&&g.steps&&g.steps.length?`<ul class="xs t2" style="margin:8px 0 0;padding-left:18px">${g.steps.slice(0,3).map(x=>`<li>${esc(typeof x==='string'?x:(x.t||x.do||''))}</li>`).join('')}</ul>`:''}</div>
 <div class="row between" style="margin-top:16px;gap:8px;flex-wrap:wrap"><button type="button" class="btn sm" id="upAck">${u.ack?'✓ Countermeasure active':'Start countermeasure'}</button><div class="row" style="gap:8px"><button type="button" class="btn sm" id="upSim">${u.sim?'Clear drift test':'Refresh'}</button>
 <button type="button" class="btn p" id="upTx" ${u.mode==='active'?'disabled':''}>${u.mode==='active'?'Transmitting…':u.mode==='acknowledged'?'Re-transmit packet':'Transmit packet to Earth'}</button></div></div></div>`);
 $('#upX').onclick=closeModal;$('#upAck').onclick=()=>uplinkAct('ack');$('#upSim').onclick=async()=>{if(u.sim){await uplinkAct('sim');closeModal()}else{await wearRefresh();openUplink()}};$('#upTx').onclick=()=>uplinkAct('transmit')}
/* polling: fast while charging or transmitting, slower otherwise, only while Live vitals is open */
const W={bat:null,up:null,t:0};
async function wearRefresh(full){const c=cur();if(!c)return;try{const r=await api(`/api/crew/${c.id}/wearable`);if(cur().id!==c.id)return;W.bat=r.battery;W.up=r.uplink;drawBattery(full);
 if(full||!$('#uplinkBox .uplink-card'))drawUplink();else{const was=$('#uplinkBox').dataset.k,k=W.up.mode+'|'+(W.up.primary&&W.up.primary.vid)+'|'+W.up.sim;$$('[data-upstatus]').forEach(e=>e.textContent=W.up.label);if(was!==k)drawUplink();$('#uplinkBox').dataset.k=k}}catch(e){}wearSchedule()}
function wearSchedule(){clearTimeout(W.t);if(U.route!=='monitor'||U.mtab!=='live'||!$('#batBox'))return;const fast=(W.bat&&W.bat.charging)||(W.up&&W.up.mode==='active');W.t=setTimeout(()=>wearRefresh(false),fast?400:3000)}

/* count tiles: scroll to the matching items and spotlight them one by one */
function spotlight(lv,btn){const more=$('#moreAtt');
 let T=[];if(lv==='1'||lv==='2'){if(more&&more.querySelector(`.att[data-lvl="${lv}"]`)){more.classList.remove('hidden');const sm=$('#showMore');if(sm)sm.textContent='Show fewer'}T=$$(`#mt .overview .att[data-lvl="${lv}"]`)}
 T=T.concat($$(`#mt .sys[data-lvl="${lv}"]`));
 if(!T.length){toast(lv==='nd'?'Every body system has data.':`No ${['nominal','warning','alert'][+lv]||''} items right now.`);return}
 $$('.spot,.spotnum').forEach(e=>{e.classList&&e.classList.remove('spot');if(e.classList&&e.classList.contains('spotnum'))e.remove()});
 btn&&btn.classList.add('pressed');setTimeout(()=>btn&&btn.classList.remove('pressed'),300);
 const mw=$('#mainwrap'),r=T[0].getBoundingClientRect(),top=mw.scrollTop+r.top-mw.getBoundingClientRect().top-120;mw.scrollTo({top:Math.max(0,top),behavior:'smooth'});
 T.forEach((el,k)=>gLaterUI(()=>{el.classList.remove('spot');void el.offsetWidth;el.classList.add('spot');const b=document.createElement('span');b.className='spotnum';b.textContent=`${k+1}/${T.length}`;el.appendChild(b);
  if(k>0){const rr=el.getBoundingClientRect();if(rr.bottom>innerHeight-20||rr.top<90)el.scrollIntoView({block:'center',behavior:'smooth'})}
  setTimeout(()=>{el.classList.remove('spot');b.remove()},2600)},420+k*520))}
const gLaterUI=(f,ms)=>setTimeout(f,ms);

/* ---- live vitals: the wearable streams on the server until the astronaut stops it ---- */
const streamOn=id=>(STATE.settings.streams||{})[id];
function monLive(){const c=cur(),on=!!streamOn(c.id);if(on)U.inject=streamOn(c.id);
 $('#mt').innerHTML=`<div class="card"><div class="row between"><div><h3>Continuous wearable data</h3><p class="s t3">The wearable streams all the time, whatever page you are on, until it is stopped here (e.g. the band is taken off). Simulated stream: each sample stands for 5 minutes. Use a test event to watch a Warning turn into an Alert.</p></div>
 <div class="row"><span class="live ${on?'on':''}" id="liveInd"><i></i><span>${on?'Streaming':'Stream off'}</span></span><select id="inject" style="width:auto"><option value="none">No test event</option><option value="mild_hr">Test: mild heart-rate rise</option><option value="hypox">Test: oxygen drop</option><option value="tachy">Test: fast heart rate</option><option value="fever">Test: fever</option><option value="spe">Test: solar particle event</option></select><button class="btn ${on?'':'p'}" id="liveBtn">${on?'Stop stream':'Start stream'}</button></div></div>
 <div id="batBox"></div><div id="uplinkBox" style="margin-top:14px"></div>
 <div class="grid cols-auto" id="tiles" style="margin-top:18px"></div><div id="liveGuide" class="stack gap8" style="margin-top:14px"></div></div>`;
 drawTiles(U.O.tiles);wearRefresh(true);$('#inject').value=U.inject;$('#inject').onchange=async e=>{U.inject=e.target.value;if(streamOn(c.id))await setStream(true)};$('#liveBtn').onclick=()=>{if(window.Notification&&Notification.permission==='default')Notification.requestPermission().catch(()=>{});setStream(!streamOn(c.id),true)};if(on)startPoll()}
function drawTiles(T,live){const box=$('#tiles');if(!box)return;box.innerHTML=T.map(t=>{const L=live&&live[t.v];const x=L?L.value:t.value,l=L?L.lvl:t.lvl,note=L?L.note:t.note;
 return`<button class="tile ${L&&L.lvl?'flash':''}" data-var="${t.v}"><span class="row between"><span class="lab">${esc(t.n)}</span>${st(l)}</span><span class="v num">${x!=null?fmt(x,t.dp):'–'}<small>${esc(t.u)}</small></span><svg class="spark" data-sp="${t.v}" preserveAspectRatio="none"></svg><span class="xs t3">Expected ${fmt(t.lo,t.dp)}–${fmt(t.hi,t.dp)}${L?' · live':t.ago!=null?' · '+ago(t.ago):''}</span>${l?`<span class="xs" style="color:${COLV[l]}">${esc(note||'')}</span>`:''}</button>`}).join('');
 bindVar(box);requestAnimationFrame(()=>T.forEach(t=>{const s=$(`[data-sp="${t.v}"]`);if(!s||t.spark.length<2)return;const W=s.clientWidth||200,H=40,xs=t.spark.map(p=>p[0]),ys=t.spark.map(p=>p[1]).concat([t.lo,t.hi]);const x0=Math.min(...xs),x1=Math.max(...xs),lo=Math.min(...ys),hi=Math.max(...ys);
  const X=x=>(x-x0)/((x1-x0)||1)*W,Y=v=>H-3-(v-lo)/((hi-lo)||1)*(H-6);s.setAttribute('viewBox',`0 0 ${W} ${H}`);s.innerHTML=`<rect x="0" width="${W}" y="${Y(t.hi)}" height="${Math.max(1,Y(t.lo)-Y(t.hi))}" rx="4" fill="#79dce8" opacity=".14"/><polyline points="${t.spark.map(p=>X(p[0])+','+Y(p[1])).join(' ')}" fill="none" stroke="#ffffff" stroke-width="1.6" stroke-linejoin="round"/>`}))}
async function setStream(on,redraw){const c=cur();const r=await api(`/api/crew/${c.id}/stream`,{body:{on,inject:U.inject}});STATE.settings.streams=r.streams;renderHeader();
 if(!redraw)return;toast(on?'Wearable stream started — it keeps running until you stop it':'Wearable stream stopped');if(!on){clearInterval(U.timer);U.O=await api(`/api/crew/${c.id}/overview?mode=${U.mode}`)}if(U.route==='monitor'&&U.mtab==='live')monLive()}
function startPoll(){clearInterval(U.timer);U.timer=setInterval(livePoll,2000);livePoll()}
async function livePoll(){const c=cur();if(U.route!=='monitor'||U.mtab!=='live'||!$('#tiles')||!c){clearInterval(U.timer);return}const r=await api(`/api/crew/${c.id}/live`);if(!r.streaming||cur().id!==c.id){clearInterval(U.timer);return}
 const live={};r.vals.forEach(v=>live[v.v]=v);drawTiles(U.O.tiles,live);const bad=r.vals.filter(v=>v.lvl>0).map(v=>({...v,n:VM(v.v).n,u:VM(v.v).u,dp:VM(v.v).dp,cond:'Live'}));const g=$('#liveGuide');if(g)g.innerHTML=bad.map(alertCard).join('')}

