function monMeasures(){const S=U.O.sched;
 const G=[['daily','Daily','Quick checks every day: blood pressure, sleep, mood, hydration, ECG, Amsler grid, reaction test.',s=>s.f==='daily'],['d2','Every 2 days','Important non-invasive exams that change within days: body mass, cardiac output, strength, near vision, saliva & breath.',s=>s.f==='d2'],
  ['d3','Every 3 days','Non-invasive imaging and samples: eye pressure, optic-nerve & jugular ultrasound, muscle ultrasound, urine & saliva.',s=>s.f==='d3'],['weekly','Weekly lab tests (invasive)','Blood draw and lab panel. The latest results stay part of monitoring until the next draw.',s=>s.inv]];
 const tone=s=>s.lvl===2?'t-bad':s.lvl===1?'t-warn':s.latest==null?'t-none':s.due?'t-due':'';
 const list=a=>`<div class="mlist">${a.map(s=>`<button class="mitem ${tone(s)}" data-var="${s.v}" title="${s.latest==null?'No data yet — click to see how to measure it':s.lvl===2?'Alert':s.lvl===1?'Warning':s.due?'Due now':'Up to date'}"><span class="dot" style="background:${s.lvl==null?NONE:COLV[s.lvl]}"></span><span class="nm">${esc(s.n)}<small>${s.due?'<b style="color:var(--warn)">Due</b>'+(s.ago!=null?' · last '+ago(s.ago):' · never measured'):'Done · '+ago(s.ago)+' · expected '+fmt(s.E,s.dp)+' '+esc(s.u)}</small></span><span class="vv num">${s.latest!=null?fmt(s.latest,s.dp):'–'}<small>${esc(s.u)}</small></span></button>`).join('')}</div>`;
 $('#mt').innerHTML=`<div class="stack gap16">${G.map(([k,n,d,f])=>{const a=S.filter(f);return`<div class="card"><div class="row between"><div><h3>${n}</h3><p class="s t3">${d}</p></div><span class="pill">${a.filter(s=>s.due).length} of ${a.length} due</span></div><div style="margin-top:12px">${list(a)}</div></div>`}).join('')}</div>`;bindVar($('#mt'))}

/* ---- drawers ---- */
function condHTML(k,compact){return`<div class="card flat"><div class="row between"><h3>${esc(k.n)}</h3>${st(k.lvl)}</div><p class="t2 s" style="margin-top:8px">${esc(k.info)}</p><p class="xs t3" style="margin-top:6px">Hazards: ${k.haz.map(esc).join(' · ')}</p>
 ${k.combo?'<div class="banner l2" style="margin-top:12px"><span class="s"><b>Several warning signs together</b> (3 or more), so this is raised to Alert.</span></div>':''}${k.sym.length?`<p class="s" style="margin-top:10px"><b>Symptoms (last 3 days):</b> ${k.sym.map(esc).join(', ')}</p>`:''}
 ${(()=>{const off=k.items.filter(i=>i.lvl),ok=k.items.filter(i=>!i.lvl);const okH=ok.map(i=>`<button class="mitem" data-var="${i.v}"><span class="dot" style="background:${COLV[0]}"></span><span class="nm">${esc(i.n)}<small>Expected ${fmt(i.E,i.dp)} ${esc(i.u)}</small></span><span class="vv num">${fmt(i.value,i.dp)}<small>${esc(i.u)}</small></span></button>`).join('');
  if(!k.items.length)return'<p class="s t3" style="margin-top:12px">No recent measurements.</p>';
  return`<div class="stack gap8" style="margin-top:14px">${off.map(i=>alertCard({...i,cond:i.calc?'calculated':''},1)).join('')}${ok.length?(off.length?`<details class="att"><summary><span class="dot" style="background:var(--ok)"></span><b class="grow">${ok.length} measure${ok.length>1?'s':''} in range</b>${CHEVD}</summary><div class="body stack gap8">${okH}</div></details>`:okH):''}</div>`})()}
 ${k.missing?`<p class="xs t3" style="margin-top:8px">${k.missing} related measure${k.missing>1?'s':''} not measured recently.</p>`:''}
 <details class="att" style="margin-top:14px" ${k.lvl?'open':''}><summary><b class="grow">${k.lvl?'Countermeasures for this condition':'How to keep it that way'}</b>${CHEVD}</summary><div class="body"><ul class="acts">${k.act.map(a=>`<li>${esc(a)}</li>`).join('')}</ul></div></details>
 <div class="banner ${k.lvl===2?'l2':'l1'}" style="margin-top:12px"><span class="s"><b>When to call the ground:</b> ${esc(k.esc)}</span></div>
 <details class="xs t3" style="margin-top:10px"><summary style="cursor:pointer">Sources</summary>${k.refs.map(r=>`<div style="margin-top:4px">${esc(r)}</div>`).join('')}</details></div>`}
async function openRegion(r){const c=cur(),R=await api(`/api/crew/${c.id}/region/${r}?mode=${U.mode}`);openDrawer(esc(R.n),R.conds.map(k=>condHTML(k)).join(''),esc(R.f));bindVar($('#drawer'))}
async function openCond(k){const c=cur(),K=await api(`/api/crew/${c.id}/condition/${k}?mode=${U.mode}`);openDrawer(esc(K.short),condHTML(K));bindVar($('#drawer'))}
async function openVar(id){const c=cur();const D=await api(`/api/crew/${c.id}/var/${id}?from=-5`);D.from=Math.max(-5,Math.min(D.today-60,0));D.to=Math.max(D.today+5,30);const L=D.latest;
 openDrawer(esc(D.n),`<div class="kpis"><div class="kpi"><span>Latest</span><b class="num">${L?fmt(L.value,D.dp):'–'}</b>${L?st(L.lvl):''}</div><div class="kpi"><span>Expected today</span><b class="num">${fmt(D.E,D.dp)}</b></div><div class="kpi"><span>Your baseline</span><b class="num">${fmt(D.base,D.dp)}</b></div></div>
 ${L&&L.lvl?`<div class="banner l${L.lvl}">${st(L.lvl)}<span class="s">${esc(L.why)}. ${esc(L.note)}</span></div>`:''}${L&&L.expBad?'<p class="s t2"><b>Note:</b> the expected in-flight value is itself outside the clinical range — typical of spaceflight but still harmful, so countermeasures apply.</p>':''}
 ${D.trend&&D.trend.bad?`<p class="s"><b>Trend:</b> over 14 days this is moving ${fmt(Math.abs(D.trend.dev),1)} σ ${D.trend.dev>0?'higher':'lower'} than your trajectory predicts.</p>`:''}
 ${guideHTML(D.guide)}<div class="card flat" style="padding:12px">${chartBox(240)}</div>
 <div class="sub"><dl class="stack gap8 s" style="margin:0"><div><dt class="t3 xs b">HOW TO MEASURE</dt><dd style="margin:0">${esc(D.how||'—')}</dd></div>${D.formula?`<div><dt class="t3 xs b">FORMULA</dt><dd style="margin:0">${esc(D.formula)}</dd></div>`:''}
 <div><dt class="t3 xs b">LIMITS</dt><dd style="margin:0">${[['wl','clinical low'],['wh','clinical high'],['cl','safety low'],['ch','safety high']].filter(([k])=>D.lims[k]!=null).map(([k,n])=>n+' '+fmt(D.lims[k],D.dp)).join(' · ')||'—'}</dd></div>
 ${D.f!=='calc'&&D.f!=='eva'?`<div><dt class="t3 xs b">YOUR RESPONSE</dt><dd style="margin:0">${fmt(D.rho,2)}× the population change (learned from ${D.rho_n} in-flight readings)</dd></div>`:''}</dl></div>
 <div class="row"><button class="btn p" id="vH">Full history</button><button class="btn" id="vL">Log a value</button></div>`,`${esc(D.u)} · ${D.inv?'lab test':D.f==='calc'?'calculated':'non-invasive'} · ${D.conds.map(esc).join(', ')}`);
 chart($('#drawer .fig'),D);$('#vH').onclick=()=>{U.hv=id;closeDrawer();location.hash='history'};$('#vL').onclick=()=>{closeDrawer();U.oneVar=id;U.logTab=CHECKIN.includes(id)?'checkin':'single';U.focusVar=CHECKIN.includes(id)?id:null;U.mtab='log';if(U.route!=='monitor')location.hash='monitor';else{$$('#mtabs [data-tab]').forEach(x=>x.setAttribute('aria-selected',x.dataset.tab==='log'));monTab()}}}

/* ================= ASSESS ================= */
VIEWS.assess=async()=>{const c=cur(),O=await api(`/api/crew/${c.id}/overview`);renderHeader(O.hdr);const ids=[...new Set(META.PANELS.filter(p=>U.assessSel.has(p.id)).flatMap(p=>p.v))];U.scen=U.scen||'typical';
 return{html:`<div class="grid split"><div class="card"><h3>1 · Choose the tests you ran</h3><div class="chips" style="margin-top:12px">${META.PANELS.map(p=>`<button class="chip" data-pn="${p.id}" aria-pressed="${U.assessSel.has(p.id)}">${esc(p.n)}</button>`).join('')}</div>
 <h3 style="margin-top:22px">2 · Enter results</h3>${imBar('imAs',{speak:'Read the results out, e.g. “hemoglobin 14.2, hematocrit 41, ionized calcium 1.21”. Tests you mention are added automatically.',photo:'Photograph the lab printout or analyser screen; values are read with OCR and the matching tests are added.',file:'Upload the lab report: CSV, Excel, JSON, PDF, Word or text. Matching tests are added automatically.'})}
 <form id="fAs" class="stack gap16" style="margin-top:12px"><div class="fgrid">${ids.map(id=>{const v=VM(id),pv=(U.asPre||{})[id];return`<label class="f${pv!=null&&U.asMsg?' hl':''}" title="${esc(v.how||'')}">${esc(v.n)}${v.u?' ('+esc(v.u)+')':''}<input inputmode="decimal" name="${id}" value="${pv??''}"></label>`}).join('')||'<p class="t3">Pick at least one test above, or speak / photograph / upload the results.</p>'}</div>
 <div class="row"><button class="btn p">Run assessment</button><button class="btn" type="button" id="asNow">Report from existing data</button></div></form></div>
 <div class="stack gap16"><div class="card hi"><h3>Run with simulated data</h3><p class="s t2" style="margin-top:6px">See the software work end-to-end without a blood draw: it generates realistic results for the chosen tests from ${esc(c.name.split(' ')[0])}’s personal expected values and runs the full assessment. Nothing is saved.</p>
  <div class="seg" style="margin-top:14px"><button data-scen="typical" aria-pressed="${U.scen==='typical'}">Typical results</button><button data-scen="issues" aria-pressed="${U.scen==='issues'}">Include abnormal results</button></div>
  <div style="margin-top:14px"><button class="btn p" id="asSim">${ICON('<path d="M5 3l14 9-14 9z"/>')}Run with simulated data</button></div></div>
 <details class="card att" style="padding:0"><summary style="padding:18px 20px"><b class="grow">How the verdict is reached</b>${CHEVD}</summary><div class="body" style="padding:0 20px 20px"><ol class="s t2" style="padding-left:20px;margin:0">
 <li>Your preflight baseline sets the start.</li><li>The sheet-2 change for &lt;30 d and &gt;30 d is blended smoothly around day 30 × your timing factor.</li><li>It is scaled by gravity (1 − g) and by how strongly you respond.</li>
 <li><b>Warning</b>: over 2 σ from your expected value or past a clinical limit. <b>Alert</b>: it persists without recovering, or a value is dangerous.</li><li>Every warning and alert comes with countermeasures checked against supplies.</li></ol></div></details></div></div><div id="report"></div>`,
 bind(){const formVals=()=>{const o={};const f=$('#fAs');if(f)for(const[k,x]of new FormData(f))if(x!=='')o[k]=x;return o};
  const rerender=async()=>{const y=$('#mainwrap').scrollTop;const v=await VIEWS.assess();$('#main').innerHTML=`<div class="page" style="animation:none">${v.html}</div>`;v.bind();$('#mainwrap').scrollTop=y};
  $$('[data-pn]').forEach(b=>b.onclick=async()=>{const k=b.dataset.pn;U.asPre=formVals();U.assessSel.has(k)?U.assessSel.delete(k):U.assessSel.add(k);rerender()});
  const allIds=[...new Set(META.PANELS.flatMap(p=>p.v))];
  bindIM('imAs',{...valueIM(allIds,async(r,out)=>{const vals=r.vals||[];if(!vals.length){out.innerHTML=esc(r.note||'No test results recognised.');return}
    const pre=formVals();let added=0;vals.forEach(v=>{pre[v.v]=v.value;if(!ids.includes(v.v))META.PANELS.filter(p=>p.v.includes(v.v)).slice(0,1).forEach(p=>{if(!U.assessSel.has(p.id)){U.assessSel.add(p.id);added++}})});
    U.asPre=pre;U.asMsg=`<span style="color:var(--ok)">✓</span> Filled ${vals.length} result${vals.length>1?'s':''}${added?` and added ${added} test${added>1?'s':''}`:''}. Check the highlighted fields, then run the assessment.`;await rerender()}),type:()=>{const i=$('#fAs input');if(i)i.focus()}});
  if(U.asMsg){$('#imAs .imout').innerHTML=U.asMsg;U.asMsg=null}
  $$('[data-scen]').forEach(b=>b.onclick=()=>{U.scen=b.dataset.scen;$$('[data-scen]').forEach(x=>x.setAttribute('aria-pressed',x===b))});
  const run=async body=>{$('#report').innerHTML='<div class="card section empty">Running assessment…</div>';const R=await api(`/api/crew/${c.id}/assess`,{body});await refreshState();renderHeader(R.hdr);showReport(R);$('#report').scrollIntoView({behavior:'smooth'})};
  $('#asNow').onclick=()=>run({values:{}});$('#asSim').onclick=()=>run({simulate:true,panels:[...U.assessSel],scenario:U.scen});
  $('#fAs').onsubmit=e=>{e.preventDefault();const v={};for(const[k,x]of new FormData(e.target))if(x!==''&&isFinite(+x))v[k]=+x;if(!Object.keys(v).length)return toast('Enter at least one value, or use simulated data');U.asPre={};run({values:v})}}}};
function showReport(R){const c=cur();const flagged=R.conds.filter(k=>k.lvl>0),ok=R.conds.filter(k=>k.lvl===0),none=R.conds.filter(k=>k.lvl==null);
 $('#report').innerHTML=`<div class="card section"><div class="row between"><div><h2>Assessment report</h2><p class="t3 s">${esc(c.name)} · mission day ${Math.floor(R.hdr.day)}${R.simulated?' · <span class="pill">simulated data — not saved</span>':''}</p></div><div class="row"><button class="btn" id="cp">Copy for downlink</button><a class="btn" id="dl" download="assessment.txt">Download</a></div></div>
 <div class="banner l${R.top}" style="margin-top:16px">${st(R.top)}<span>${esc(R.verdict)}</span></div>
 ${R.simulated?`<details class="att" style="margin-top:14px"><summary><b class="grow">Simulated values used (${Object.keys(R.simulated).length})</b>${CHEVD}</summary><div class="body"><div class="chips">${Object.entries(R.simulated).map(([k,v])=>`<span class="chip">${esc(VM(k).n)}: <b class="num">${fmt(v,VM(k).dp)}</b> ${esc(VM(k).u)}</span>`).join('')}</div></div></details>`:''}
 ${R.calc.length?`<h4 style="margin-top:20px">Calculated from this assessment</h4><div class="chips" style="margin-top:8px">${R.calc.map(x=>`<span class="chip"><span class="dot" style="background:${COLV[x.lvl]};margin-right:6px"></span>${esc(x.n)}: <b class="num">${fmt(x.value,x.dp)}</b> ${esc(x.u)}</span>`).join('')}</div>`:''}
 ${flagged.length?`<h4 style="margin-top:22px">Needs attention</h4><div class="grid" style="margin-top:10px;grid-template-columns:repeat(auto-fill,minmax(min(100%,520px),1fr))">${flagged.map(k=>condHTML(k)).join('')}</div>`:''}
 ${ok.length?`<h4 style="margin-top:22px">Within range</h4><div class="syslist" style="margin-top:10px">${ok.map(k=>`<button class="sys" data-cond="${k.id}"><span class="dot" style="background:var(--ok)"></span><span class="nm">${esc(k.short)}<small>${k.count} measures in range</small></span></button>`).join('')}</div>`:''}
 ${none.length?`<p class="xs t3" style="margin-top:14px">No data: ${none.map(k=>esc(k.short)).join(', ')}.</p>`:''}</div>`;
 bindVar($('#report'));$$('#report [data-cond]').forEach(b=>b.onclick=()=>openCond(b.dataset.cond));
 $('#dl').href=URL.createObjectURL(new Blob([R.text],{type:'text/plain'}));$('#cp').onclick=()=>navigator.clipboard.writeText(R.text).then(()=>toast('Report copied')).catch(()=>toast('Copy was blocked'))}

/* ================= SPACEWALK ================= */
VIEWS.eva=async()=>{const c=cur(),[E,O,K]=await Promise.all([api(`/api/crew/${c.id}/eva`),api(`/api/crew/${c.id}/overview`),api(`/api/crew/${c.id}/condition/eva`)]);renderHeader(O.hdr);const lv=E.verdict==='Go'?0:E.verdict==='No-go'?2:1;
 const P=META.PANELS.find(p=>p.id==='eva');const fails=E.checks.filter(x=>!x.ok),oks=E.checks.filter(x=>x.ok);
 return{html:`<div class="grid split"><div class="card hi"><div class="row between"><div><h3>Spacewalk readiness</h3><p class="s t3">From ${esc(c.name)}’s latest data — re-run on EVA morning.</p></div><span style="font:600 26px var(--hf);color:${COLV[lv]}">${esc(E.verdict)}</span></div>
  <div class="stack gap8" style="margin-top:16px">${fails.map(x=>`<div class="sub row" style="align-items:flex-start;gap:12px"><span class="dot" style="background:${x.sev==='nogo'?'var(--bad)':'var(--warn)'};margin-top:7px"></span><div class="grow"><b>${esc(x.t)}</b><div class="s t2">${esc(x.detail)}</div></div>${st(x.sev==='nogo'?2:1,x.sev==='nogo'?'No-go':'Caution')}</div>`).join('')}</div>
  <details class="att" style="margin-top:10px"><summary><b class="grow">${oks.length} checks passed</b>${CHEVD}</summary><div class="body stack gap4">${oks.map(x=>`<div class="suprow"><span>${esc(x.t)}</span><span class="t3 s">${esc(x.detail)}</span></div>`).join('')}</div></details></div>
 <div class="card"><h3>Log a spacewalk debrief</h3><p class="s t3" style="margin-top:4px">Suit telemetry and post-EVA findings. Any decompression-sickness sign raises an immediate alert.</p>
  ${imBar('imEva',{speak:'Say the debrief, e.g. “suit CO2 3.1, peak heart rate 82 percent, oxygen left 31 percent, hand pain 2”.',photo:'Photograph the suit telemetry screen or the paper debrief sheet; values are read with OCR.',file:'Upload the suit telemetry export or debrief form (CSV, Excel, JSON, PDF, Word or text).'})}
  <form id="fE" class="stack gap16" style="margin-top:14px"><div class="fgrid">${P.v.map(id=>{const v=VM(id);return`<label class="f" title="${esc(v.how||'')}">${esc(v.n)}${v.u?' ('+esc(v.u)+')':''}<input inputmode="decimal" name="${id}"></label>`}).join('')}</div><div><button class="btn p">Save debrief</button></div></form><div id="evaFb" class="stack gap8" style="margin-top:12px"></div></div></div>
 <div class="grid split section">${condHTML(K)}<div class="card"><h3>About this risk</h3><p class="s t2" style="margin-top:8px">${esc(K.info)}</p><h4 style="margin-top:16px">Precautions</h4><ul class="acts s">${K.act.map(a=>`<li>${esc(a)}</li>`).join('')}</ul>
  <h4 style="margin-top:16px">Past spacewalks</h4><p class="s t2">${E.evas.length?E.evas.map(d=>'Day '+fmt(d,0)).join(' · '):'None logged'}</p></div></div>`,
 bind(){bindVar();bindIM('imEva',{...valueIM(P.v,(r,out)=>fillForm($('#fE'),r,out)),type:()=>$('#fE input').focus()});if(U.focusVar){const el=$(`#fE [name="${U.focusVar}"]`);U.focusVar=null;if(el){el.closest('label').classList.add('hl');setTimeout(()=>{el.scrollIntoView({block:'center',behavior:'smooth'});el.focus({preventScroll:true})},250)}}$('#fE').onsubmit=e=>{e.preventDefault();const items=[...new FormData(e.target)].filter(([k,v])=>v!==''&&isFinite(+v)).map(([k,v])=>({v:k,value:+v,src:'m'}));if(!items.length)return toast('Enter at least one value');
  saveItems(items,async(r,bad)=>{e.target.reset();$('#evaFb').innerHTML=bad.map(f=>alertCard({...f,dp:VM(f.v).dp,cond:'Spacewalk'})).join('')||st(0,'All debrief values within range')})}}}};

/* ================= HISTORY ================= */
function rangeOf(D){const R=U.range,t=D.today;if(R.kind==='last')return[Math.max(-5,t-R.n),t+1];if(R.kind==='first')return[0,Math.min(R.n,Math.max(t,R.n))];if(R.kind==='custom')return[R.from,R.to];
 return[Math.min(-3,D.pts.length?D.pts[0].day:0),t+3]}
VIEWS.history=async()=>{const c=cur(),id=U.hv;const D=await api(`/api/crew/${c.id}/var/${id}?from=-30&to=2000`);const O=await api(`/api/crew/${c.id}/overview`);renderHeader(O.hdr);
 const[fr,to]=rangeOf(D);const D2=await api(`/api/crew/${c.id}/var/${id}?from=${fr}&to=${to}`);D.band=D2.band;D.from=fr;D.to=to;const inR=D.pts.filter(p=>p.day>=fr&&p.day<=to);const R=U.range;
 const pres=[['last',14,'Last 14 d'],['last',30,'Last 30 d'],['last',90,'Last 90 d'],['first',14,'First 14 d'],['first',30,'First 30 d'],['all',0,'Whole mission'],['custom',0,'Custom…']];
 const unitSel=U.rUnit||'day';const toDate=d=>dayToDate(c,d).toISOString().slice(0,10);
 return{html:`<div class="card"><div class="row between"><label class="f" style="flex:1;min-width:240px;max-width:460px">Measure<select id="hv">${varOptions(id)}</select></label><div class="stack gap4" style="align-items:flex-end"><span class="xs t3 b">TIME RANGE</span><div class="seg">${pres.map(([k,n,l])=>`<button data-rk="${k}" data-rn="${n}" aria-pressed="${R.kind===k&&(R.n===n||k==='all'||k==='custom')}">${l}</button>`).join('')}</div></div></div>
 <div id="custom" class="sub ${R.kind==='custom'?'':'hidden'}" style="margin-top:14px"><div class="row" style="align-items:flex-end"><div class="seg"><button data-ru="day" aria-pressed="${unitSel==='day'}">Mission day</button><button data-ru="date" aria-pressed="${unitSel==='date'}">Calendar date</button></div>
  <label class="f">From<input id="rf" ${unitSel==='date'?`type="date" value="${toDate(fr)}"`:`inputmode="decimal" value="${fmt(fr,0)}"`} style="width:170px"></label><label class="f">To<input id="rt" ${unitSel==='date'?`type="date" value="${toDate(to)}"`:`inputmode="decimal" value="${fmt(to,0)}"`} style="width:170px"></label><button class="btn p" id="rgo">Apply</button></div></div>
 <p class="s t2" style="margin-top:14px">Showing <b>day ${fmt(fr,0)} → day ${fmt(to,0)}</b> <span class="t3">(${dstr(dayToDate(c,fr))} – ${dstr(dayToDate(c,to))})</span> · ${inR.length} of ${D.n_total} records · ${esc(D.u)}</p>
 <div style="margin-top:10px">${chartBox(380)}</div><div style="margin-top:10px">${chartLegend()}</div></div>
 <div class="grid split section"><div class="card"><div class="row between"><h3>Records in range</h3><span class="row" style="gap:8px"><button class="btn sm danger hidden" id="hDelSel">Delete selected</button><a class="btn sm" id="csv" download="${esc(id)}.csv">Download CSV</a></span></div><div class="scroll" id="hScroll" style="max-height:420px;overflow:auto;margin-top:8px"><table class="rtable"><thead><tr><th>Day</th><th>Date</th><th class="r">Value</th><th>Source</th><th>Status</th><th class="r"><label class="selall" title="Select all"><input type="checkbox" id="hSelAll"></label></th></tr></thead><tbody>
  ${inR.slice().reverse().slice(0,300).map(p=>`<tr><td data-l="Day">${fmt(p.day,1)}</td><td data-l="Date" class="s t2">${dstr(dayToDate(c,p.day))}</td><td class="r num b" data-l="Value">${fmt(p.val,D.dp)}</td><td data-l="Source" class="s t2">${esc(p.src)}</td><td>${st(p.lvl)}</td><td class="r"><span class="row" style="gap:6px;justify-content:flex-end"><button class="btn ghost sm danger" data-del="${p.id}">Delete</button><input type="checkbox" class="hsel" data-sel="${p.id}" aria-label="Select record"></span></td></tr>`).join('')||'<tr><td colspan="6" class="t3">No records in this range.</td></tr>'}</tbody></table></div></div>
 <div class="card"><h3>About this measure</h3><div class="kpis" style="margin-top:14px"><div class="kpi"><span>Baseline</span><b class="num">${fmt(D.base,D.dp)}</b></div><div class="kpi"><span>Expected today</span><b class="num">${fmt(D.E,D.dp)}</b></div>${D.f!=='calc'&&D.f!=='eva'?`<div class="kpi"><span>Your response</span><b class="num">${fmt(D.rho,2)}×</b></div>`:''}</div>
  ${D.dose?`<p class="s" style="margin-top:12px">Cumulative dose ${fmt(D.dose.cum,1)} mSv this mission · ${fmt(D.dose.d30,1)} mSv in 30 d (limit 250) · career limit 600 mSv.</p>`:''}<p class="s t2" style="margin-top:12px">${esc(D.how||D.formula||'')}</p>${guideHTML(D.guide)}</div></div>`,
 bind(){chart($('#main .fig'),D);$('#hv').onchange=e=>{U.hv=e.target.value;render()};
  $$('[data-rk]').forEach(b=>b.onclick=()=>{const k=b.dataset.rk;if(k==='custom'){U.range={kind:'custom',from:fr,to};$('#custom').classList.remove('hidden');$$('[data-rk]').forEach(x=>x.setAttribute('aria-pressed',x===b));return}U.range={kind:k,n:+b.dataset.rn};render()});
  $$('[data-ru]').forEach(b=>b.onclick=()=>{U.rUnit=b.dataset.ru;U.range={kind:'custom',from:fr,to};render()});
  $('#rgo').onclick=()=>{const a=$('#rf').value,b=$('#rt').value;let f,t;if((U.rUnit||'day')==='date'){f=dateToDay(c,a);t=dateToDay(c,b)}else{f=+a;t=+b}if(!isFinite(f)||!isFinite(t)||t<=f)return toast('Choose an end after the start');U.range={kind:'custom',from:f,to:t};render()};
  $('#csv').href=URL.createObjectURL(new Blob(['mission_day,date,value,unit,source,status\n'+inR.map(p=>`${p.day},${dayToDate(c,p.day).toISOString().slice(0,10)},${p.val},${D.u},${p.src},${LVN[p.lvl]}`).join('\n')],{type:'text/csv'}));
  const undoToast=(recs,msg)=>{toast(`${msg} <button class="btn ghost sm" id="undo">Undo</button>`,6000);$('#undo').onclick=async()=>{$('#toast').classList.remove('on');await api(`/api/crew/${cur().id}/records`,{body:{items:recs.map(r=>({v:r[1],day:r[2],value:r[3],src:r[4]}))}});await refreshAfterEdit();toast('Restored')}};
  const fadeRows=ids=>Promise.all(ids.map(id=>{let tr=$(`[data-del="${id}"]`);tr=tr&&tr.closest('tr');return new Promise(res=>{if(!tr)return res();tr.classList.add('rowout');setTimeout(res,260)})}));
  const refreshAfterEdit=async()=>{const O=await api(`/api/crew/${cur().id}/overview?mode=${U.mode}`);U.O=O;await render();updateNavDots()};
  $$('[data-del]').forEach(b=>b.onclick=async()=>{const id=b.dataset.del;const[r]=await Promise.all([api('/api/records/'+id,{method:'DELETE'}),fadeRows([id])]);await refreshAfterEdit();undoToast([r.rec],'Record deleted.')});
  const selUI=()=>{const n=$$('.hsel:checked').length,btn=$('#hDelSel');btn.classList.toggle('hidden',!n);btn.textContent=`Delete selected (${n})`;const all=$$('.hsel');$('#hSelAll').checked=all.length&&n===all.length;$('#hSelAll').indeterminate=n>0&&n<all.length;$$('.hsel').forEach(x=>x.closest('tr').classList.toggle('rsel',x.checked))};
  $$('.hsel').forEach(x=>x.onchange=selUI);const sa=$('#hSelAll');if(sa)sa.onchange=e=>{$$('.hsel').forEach(x=>x.checked=e.target.checked);selUI()};
  $('#hDelSel').onclick=async()=>{const ids=$$('.hsel:checked').map(x=>x.dataset.sel);if(!ids.length)return;if(ids.length>3&&!(await ask(`<h3>Delete ${ids.length} records?</h3><p class="s t2" style="margin-top:6px">${esc(VM(id).n)} · you can undo right after.</p>`,'Delete',true)))return;
   const[r]=await Promise.all([api('/api/records-delete',{body:{ids}}),fadeRows(ids)]);await refreshAfterEdit();undoToast(r.recs,`${r.recs.length} record${r.recs.length>1?'s':''} deleted.`)}}}};

/* ================= ROUTINE ================= */
